  ('feat.archetype.cavalier.cavalier_dedication', NULL, NULL, 'archetype.cavalier', 'Arquétipo', 2, 'Dedicação de Cavaleiro', 'Cavalier Dedication', 'Dedicación de caballero', 'Adquire um companheiro animal jovem que serve como sua montaria; ele deve ser pelo menos um tamanho maior que você.', 'Gain a young animal companion as a mount; it must be at least one size larger than you.', 'Obtienes un compañero animal joven como montura; debe ser al menos un tamaño mayor que tú.', NULL, NULL, ARRAY['Arquétipo']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 195, '{"effects":[],"needs_review":false}'::jsonb),
  ('feat.archetype.cavalier.knights_banner', NULL, NULL, 'archetype.cavalier', 'Arquétipo', 4, 'Estandarte do Cavaleiro', 'Knight''s Banner', 'Estandarte del caballero', 'Ergue o estandarte do juramento na montaria e inspira aliados próximos contra efeitos de medo.', 'Raise your oath''s banner on your mount and inspire nearby allies against fear effects.', 'Alzas el estandarte de tu juramento en tu montura e inspiras a los aliados cercanos contra el miedo.', NULL, NULL, ARRAY['Arquétipo']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 195, '{"effects":[],"needs_review":false}'::jsonb),
  ('feat.archetype.cavalier.knights_charge', NULL, NULL, 'archetype.cavalier', 'Arquétipo', 4, 'Investida do Cavaleiro', 'Knight''s Charge', 'Carga del caballero', 'Comanda a montaria para Andar duas vezes e realiza um Golpe durante o movimento.', 'Command your mount to Stride twice and make a Strike during the movement.', 'Ordenas a tu montura Avanzar dos veces y haces un Golpe durante el movimiento.', NULL, NULL, ARRAY['Arquétipo']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 195, '{"effects":[],"needs_review":false}'::jsonb),
